<div class="row"><div class="col-md-6"><div class="card card-warning"><div class="card-header"><h3 class="card-title"><i class="fas fa-exclamation-triangle mr-1"></i>Low Stock Alert</h3></div><div class="card-body table-responsive p-0"><table class="table table-hover"><thead><tr><th>Product</th><th>Quantity</th><th>Reorder Level</th></tr></thead><tbody><?php if($low->num_rows===0):?><tr><td colspan="3">No low-stock products.</td></tr><?php else: while($r=$low->fetch_assoc()):?><tr><td><?=e($r['name'])?></td><td><span class="badge badge-danger"><?=$r['quantity']?></span></td><td><?=$r['reorder_level']?></td></tr><?php endwhile; endif;?></tbody></table></div></div></div><div class="col-md-6"><div class="card"><div class="card-header"><h3 class="card-title">Recent Sales</h3><a href="sales_history.php" class="btn btn-sm btn-primary float-right">View all</a></div><div class="card-body table-responsive p-0"><table class="table table-striped"><thead><tr><th>Sale #</th><th>Date</th><th>Total</th></tr></thead><tbody><?php if(!$recent->num_rows):?><tr><td colspan="3">No sales recorded yet.</td></tr><?php else:while($r=$recent->fetch_assoc()):?><tr><td>#<?=$r['id']?></td><td><?=e($r['sold_at'])?></td><td><?=money($r['total'])?></td></tr><?php endwhile;endif;?></tbody></table></div></div></div></div>
